<?php
/** Proof — a drop is a transition (spec "Proof", 4–5): the expanded card for a resolution code; Confirm → solved with ticket.transition (via board) and board.move; a Closed card → 422 in the sentence; a requester's forced POST → 403; a drop within a column survives a reload; the no-JS select lists hd_transition()'s moves and the plain POST lands the card. */
require __DIR__ . '/lib.php';
$W = world();
$marco = as_member(27); $lena = as_member(28); $priya = as_member(26);
$t = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE drop me', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
$num = ticket_row($t)['number'];
echo "1. New → Open by a drop (the drag's HTMX post)\n";
$since = last_activity_id();
[$c, $body, $h] = hx($marco, '/board/move.php', ['ticket' => $t, 'column' => 'open', 'position' => 0, 'view' => 'team_board'], '#board-card-' . $t);
ok($c === 200 && str_contains($body, 'id="board-card-' . $t . '"') && str_contains($body, 'data-column="open"') && preg_match('/^HX-Trigger: .*ticketChanged/mi', $h) === 1, 'the response is the card re-rendered in Open with HX-Trigger ticketChanged');
ok(ticket_status($t) === 'open' && (int) ticket_row($t)['board_position'] === 0, 'open, ranked first');
$tr = array_values(array_filter(activity('ticket.transition', $since), fn ($r) => (int) $r['ticket_id'] === $t));
$bm = array_values(array_filter(activity('board.move', $since), fn ($r) => (int) $r['ticket_id'] === $t));
ok(count($tr) === 1 && json_decode($tr[0]['after'], true)['via'] === 'board' && count($bm) === 1 && json_decode($bm[0]['before'], true)['column'] === 'new' && json_decode($bm[0]['after'], true)['column'] === 'open' && json_decode($bm[0]['after'], true)['position'] === 0 && (int) $bm[0]['queue_id'] === $W['it'], 'one ticket.transition (via board) and one board.move (before new, after open, position 0, queue_id)');
ok(str_contains($body, 'id="board-column-open-count"') && str_contains($body, 'hx-swap-oob="true"'), 'the two columns\' counts come out-of-band');
echo "2. Open → Solved needs a resolution code\n";
[$c, $body, $h] = hx($marco, '/board/move.php', ['ticket' => $t, 'column' => 'solved', 'view' => 'team_board'], '#board-card-' . $t);
ok($c === 200 && str_contains($body, 'id="board-card-' . $t . '-confirm"') && str_contains($body, 'name="resolution_code"') && str_contains($body, 'id="board-card-' . $t . '-confirm-btn"') && str_contains($body, 'id="board-card-' . $t . '-cancel-btn"'), 'the card comes back expanded with a resolution-code select, Confirm and Cancel');
ok(ticket_status($t) === 'open', 'nothing moved yet');
$since = last_activity_id();
[$c, $body, $h] = hx($marco, '/board/move.php', ['ticket' => $t, 'column' => 'solved', 'resolution_code' => 'resolved', 'view' => 'team_board'], '#board-card-' . $t);
ok($c === 200 && ticket_status($t) === 'solved' && ticket_row($t)['resolution_code'] === 'resolved', 'Confirm with resolved: solved');
ok(count(array_filter(activity('ticket.transition', $since), fn ($r) => (int) $r['ticket_id'] === $t)) === 1 && count(array_filter(activity('board.move', $since), fn ($r) => (int) $r['ticket_id'] === $t)) === 1, 'one ticket.transition and one board.move');
ok(count(outbox($t, 'replied')) === 1, 'the requester is told it is solved (as the ticket page does)');
echo "3. What is refused\n";
act($lena, '/tickets/close.php', ['ticket' => $t, 'resolution_code' => 'resolved']);
[$c, $body, $h] = hx($marco, '/board/move.php', ['ticket' => $t, 'column' => 'open', 'view' => 'team_board'], '#board-card-' . $t);
ok($c === 422 && str_contains(html_entity_decode($body, ENT_QUOTES), $num . ' cannot move from Closed.') && preg_match('/^HX-Retarget: #flash/mi', $h) === 1, 'a Closed card dropped: 422 "' . $num . ' cannot move from Closed." retargeted to #flash (the card springs back)');
[$c, $b] = act($marco, '/board/move.php', ['ticket' => $t, 'column' => 'nowhere', 'view' => 'team_board']);
ok($c === 422 && isset(fields($b)['column']), 'an unknown column: 422');
$own = $W['t_p1'];
[$c, $b] = act($priya, '/board/move.php', ['ticket' => $own, 'column' => 'open']);
ok($c === 403, 'Priya\'s forced POST on her own ticket: 403');
[$c, $b] = act($priya, '/board/move.php', ['ticket' => $W['t_jo'], 'column' => 'open']);
ok($c === 404, 'and on one she cannot see: 404');
[$c, $b] = act($marco, '/board/move.php', ['ticket' => $W['t_jo2'], 'column' => 'closed', 'resolution_code' => 'resolved', 'view' => 'team_board']);
ok($c === 422 && msg($b) === 'Closing early needs the Lead role.', 'open → closed by support: the Lead sentence');
echo "4. Within a column: the order survives a reload\n";
$x = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE rank x', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
$y = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE rank y', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
$z = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE rank z', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
[$c, $d] = board($marco);
$newCol = columns_of($d)['new'];
ok(array_slice($newCol, 0, 3) === [$z, $y, $x], 'three new cards: newest first by last activity (' . implode(',', array_slice($newCol, 0, 3)) . ')');
$since = last_activity_id();
[$c, $body, $h] = hx($marco, '/board/reorder.php', ['ticket' => $x, 'position' => 0, 'view' => 'team_board']);
ok($c === 204, 'board_reorder answers 204 for HTMX');
[$c, $body, $h] = hx($marco, '/board/reorder.php', ['ticket' => $y, 'position' => 1, 'view' => 'team_board']);
[$c, $d] = board($marco);
$newCol = columns_of($d)['new'];
ok(array_slice($newCol, 0, 3) === [$x, $y, $z], 'after ranking x first and y second: x, y, z (' . implode(',', array_slice($newCol, 0, 3)) . ')');
[$c, $d] = board($marco);
ok(array_slice(columns_of($d)['new'], 0, 3) === [$x, $y, $z], 'and again on a reload');
ok(count(activity('board.reorder', $since)) === 2 && json_decode(activity('board.reorder', $since)[0]['after'], true)['position'] === 0, 'board.reorder logged with the position');
[$c, $b] = act($marco, '/board/reorder.php', ['ticket' => $x, 'position' => '-1']);
ok($c === 422, 'a negative rank: 422');
echo "5. No JavaScript: the select and the plain POST\n";
$body = page($marco, '/board')['body'];
preg_match('/<select name="column"[^>]*id="board-card-' . $y . '-move-select"[^>]*>(.*?)<\/select>/s', $body, $m);
preg_match_all('/<option value="([a-z_]+)"/', $m[1] ?? '', $opts);
$allowed = array_map(fn ($mv) => $mv['key'], array_filter(q('SELECT s.key, t.needs_right FROM ticket_statuses s JOIN LATERAL hd_transition(:from, s.id) t ON true WHERE s.archived_at IS NULL AND s.id <> :from ORDER BY s.sort_order', ['from' => (int) ticket_row($y)['status_id']]), fn ($r) => $r['needs_right'] === 'tickets.work'));
sort($allowed); $got = $opts[1] ?? []; sort($got);
ok($got === $allowed && $allowed !== [], 'the card\'s "Move to…" lists exactly hd_transition()\'s moves for support from New: ' . implode(', ', $got));
[$c, $h] = plain($marco, '/board/move.php', ['ticket' => $y, 'column' => 'open', 'view' => 'team_board']);
ok($c === 302 && preg_match('#^Location: /board\?view=team_board&notice=moved#mi', $h) === 1, 'the plain POST: 302 back to the board');
[$c, $d] = board($marco);
ok(column_of($d, $y) === 'open', 'and the card is in Open on reload');
[$c, $h] = plain($marco, '/board/move.php', ['ticket' => $y, 'column' => 'solved', 'view' => 'team_board']);
ok($c === 302 && preg_match('#^Location: /board\?view=team_board&expand=' . $y . '&to=solved#mi', $h) === 1, 'a move needing a field: 302 to the board with ?expand=&to=');
$body = page($marco, '/board?view=team_board&expand=' . $y . '&to=solved')['body'];
ok(str_contains($body, 'id="board-card-' . $y . '-confirm"') && str_contains($body, 'name="resolution_code"'), 'which renders that card expanded');
echo "6. Other column fields\n";
[$c, $b] = act($lena, '/views/save.php', ['name' => 'SMOKE priority board', 'scope' => 'global', 'layout' => 'board', 'filters' => json_encode(['queue_id' => [$W['it']]]), 'board' => json_encode(['column_field' => 'priority'])]);
$pv = (int) $b['record_id'];
$since = last_activity_id();
[$c, $b] = act($marco, '/board/move.php', ['ticket' => $z, 'column' => 'urgent', 'view' => $pv]);
ok($c === 200 && ticket_row($z)['priority'] === 'urgent' && count(array_filter(activity('ticket.set_fields', $since), fn ($r) => (int) $r['ticket_id'] === $z)) === 1 && count(activity('board.move', $since)) === 1, 'a priority board: the drop is ticket_set_fields plus board.move');
[$c, $b] = act($lena, '/views/save.php', ['name' => 'SMOKE assignee board', 'scope' => 'global', 'layout' => 'board', 'filters' => json_encode(['queue_id' => [$W['it']]]), 'board' => json_encode(['column_field' => 'assignee'])]);
$av = (int) $b['record_id'];
$since = last_activity_id();
[$c, $b] = act($marco, '/board/move.php', ['ticket' => $z, 'column' => '28', 'view' => $av]);
ok($c === 200 && (int) ticket_row($z)['assignee_member_id'] === 28 && count(array_filter(activity('ticket.assign', $since), fn ($r) => (int) $r['ticket_id'] === $z)) === 1 && count(outbox($z, 'assigned')) === 1, 'an assignee board: the drop is ticket_assign; Lena is told (' . $c . ' ' . msg($b) . ' assignee ' . ticket_row($z)['assignee_member_id'] . ', assign rows ' . count(array_filter(activity('ticket.assign', $since), fn ($r) => (int) $r['ticket_id'] === $z)) . ', outbox ' . count(outbox($z, 'assigned')) . ')');
[$c, $b] = act($marco, '/board/move.php', ['ticket' => $z, 'column' => '40', 'view' => $av]);
ok($c === 200 && count(dispatches($z)) === 1, 'dropped on the agent: dispatched');
[$c, $b] = act($marco, '/board/move.php', ['ticket' => $z, 'column' => '29', 'view' => $av]);
ok($c === 422 && str_contains(msg($b), 'is not in the'), 'dropped on someone outside the queue: 422');
finish();
